const wasteChoices = [["市が進めている案","新設＋20年間の運営を一体契約","整備117.54億円＋20年間運営91.08億円＝208.62億円（2026年4月再精査）。旧施設解体・汚染対策16.62億円は別。","ごみ処理能力・契約後の確定額、物価変動、広域需要、災害時継続、長期運営の成果指標","公表された整備方針"],["未検証の比較案","既存施設を一部改修して延命","同じ条件での費用試算は現時点で確認できません。ゼロ円と扱わない。","どの設備が延命可能か。老朽化・耐震・安全、工事中の処理の継続、追加工事リスク","技術調査が必要"],["未検証の比較案","規模縮小・段階的な更新","施設別に分けた整備費・30年維持費を試算してから比較。","今後の分別・ごみ量推計、将来更新箇所、処理休止期間、一部設備の耐用年数","需要予測が必要"],["未検証の比較案","近隣自治体との共同処理","受入先や輸送の条件が定まっていないため、節減額は未確認。","近隣施設の余力、行政間協定、追加運搬距離と排出量、災害時のバックアップ","受入先との協議が必要"],["計画と組み合わせる案","回収・リユース強化で処理量を減らす","処理量減による施設規模削減効果は別途検証が必要。","分別回収率、粗大ごみの再使用、住民の負担、対象品目、民間事業者との連携","既存計画との併用も可能"]];
const d32 = JSON.parse(document.getElementById('v32Data').textContent);
const budget = d32.budget;
const $ = x => document.getElementById(x);
const esc = x => String(x??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const f = (x,n=1) => Number(x).toLocaleString('ja-JP',{maximumFractionDigits:n,minimumFractionDigits:n});
const clamp = (x,min,max) => Math.max(min,Math.min(max,x));
const palette = ['#197e5b','#db916e','#587db7','#a187b9','#d1a752'];
const readout = (target,txt) => { const node=$(target); if(node) node.textContent = txt; };
function table(headers,rows){return `<div class="v33-table-scroll"><table class="v33-table"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function plot({series, years, title, unit, axisMin=0, axisMax=null, width=830, height=275, readoutId=null, connectGaps=false, left=50, right=20}){
 const top=24,base=height-42, w=width-left-right, h=base-top;
 const all=series.flatMap(s=>s.values.filter(v=>Number.isFinite(v)));
 const lo=axisMin,hi=axisMax??Math.ceil(Math.max(...all,1)*1.10);
 const xx=i=>left + (i/(years.length-1))*w;
 const yy=v=>base -(v-lo)/(hi-lo||1)*h;
 let html=`<div class="v33-svg-wrap"><svg class="v33-line-svg" role="group" aria-label="${esc(title)}" viewBox="0 0 ${width} ${height}">`;
 for(let j=0;j<4;j++){
  const v=lo+(hi-lo)*j/3,Y=yy(v);
  html+=`<line x1="${left}" x2="${width-right}" y1="${Y}" y2="${Y}" stroke="#d8e5dc" stroke-dasharray="3 5"/><text x="${left-9}" y="${Y+4}" text-anchor="end" fill="#607668" font-size="11">${esc(f(v,0))}</text>`;
 }
 // Shaded prior mayor period—do not imply mayoral causality
 if(years.length>=20&&+years[0]<=1996){
  const s=xx(0)-5,e=xx(years.indexOf(2006));
  html+=`<rect x="${s}" y="${top}" width="${e-s}" height="${h}" fill="#f5e7c7" opacity=".34" pointer-events="none"/><line x1="${e}" x2="${e}" y1="${top}" y2="${base}" stroke="#b7995c" stroke-dasharray="4 6"/>`;
 }
 series.forEach((s,j)=>{
  let runs=[],cur=[];
  s.values.forEach((v,i)=>{
   if(Number.isFinite(v)){
    if(cur.length && !connectGaps && i-cur[cur.length-1].i>1){runs.push(cur);cur=[];}
    cur.push({i,v});
   }else if(cur.length && !connectGaps){runs.push(cur);cur=[];}
  });if(cur.length)runs.push(cur);
  runs.forEach(run=>{if(run.length>=2){const path=run.map((r,k)=>(k?'L':'M')+xx(r.i).toFixed(1)+','+yy(r.v).toFixed(1)).join(' ');html+=`<path d="${path}" fill="none" stroke="${s.color||palette[j]}" stroke-width="3.8" stroke-linecap="round" stroke-linejoin="round"/>`;}});
  s.values.forEach((v,i)=>{if(!Number.isFinite(v))return;
   html+=`<circle role="button" tabindex="0" data-plot="${esc(readoutId||'')}" data-year="${years[i]}" data-name="${esc(s.name)}" data-value="${esc(f(v,2))}" data-unit="${esc(unit)}" aria-label="${years[i]}年度 ${esc(s.name)} ${esc(f(v,2))}${esc(unit)}" cx="${xx(i)}" cy="${yy(v)}" r="6.5" fill="${s.color||palette[j]}" stroke="white" stroke-width="2.7"/>`;
  });
 });
 const tickStep=years.length>15?5:1;
 years.forEach((v,i)=>{if(i%tickStep===0||i===years.length-1)html+=`<text x="${xx(i)}" y="${base+23}" text-anchor="middle" fill="#52695a" font-size="12">${String(v).replace('年度','')}</text>`;});
 html+=`</svg></div><div class="v33-line-legend">${series.map((s,j)=>`<span><i style="background:${s.color||palette[j]}"></i>${esc(s.name)}</span>`).join('')}</div>`;
 return html;
}
// Delegated across all dynamically created SVGs, works with mouse, touch, keyboard
function bindGraph(){
 document.addEventListener('click',event=>{
  const c=event.target.closest('circle[data-plot]');if(c){
    const target=c.dataset.plot, message=`${c.dataset.year}年度　${c.dataset.name}：${c.dataset.value}${c.dataset.unit}`;
    if(target)readout(target,message);
    const svg=c.closest('svg');svg?.querySelectorAll('circle[data-plot]').forEach(p=>p.classList.remove('v33-focused'));
    c.classList.add('v33-focused');return;
  }
  const b=event.target.closest('[data-v33-bar]');if(b){readout('v33BudgetReadout',`${b.dataset.v33Bar}：${b.dataset.value}億円（2026年度当初予算）`);document.querySelectorAll('[data-v33-bar]').forEach(p=>p.classList.remove('v33-focused'));b.classList.add('v33-focused');}
 });
 document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('circle[data-plot]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
}
