let currentExpense=budget[0].key;const bmode={};
function budgetBars(parts,total){
 const max=Math.max(1,...parts.map(p=>p.value));
 return `<div class="v33-bars-xscroll"><div class="v33-bars" style="--bcount:${parts.length}">${parts.map((p,i)=>{const n=Math.round(p.value/max*100);return `<button type="button" class="v33-bar" data-v33-bar="${esc(p.name)}" data-value="${f(p.value,2)}" title="${esc(p.desc||'')}"><span class="v33-bar-num">${f(p.value,2)}</span><span class="v33-bar-rail"><i style="height:${n}%;background:${palette[i%palette.length]}"></i></span><span class="v33-bar-caption">${esc(p.name)}</span></button>`;}).join('')}</div></div>`;
}
function renderBudget(){
 const b=budget.find(x=>x.key===currentExpense)||budget[0];
 if(!$('v32BudgetChart'))return;
 $('v32BudgetSelect').innerHTML=budget.map(x=>`<button type="button" role="tab" data-v33-expense="${x.key}" aria-selected="${x.key===currentExpense}" aria-pressed="${x.key===currentExpense}" tabindex="${x.key===currentExpense?0:-1}">${esc(x.name)}</button>`).join('');
 $('v32BudgetHeading').innerHTML=`<div class="v34-budget-heading"><span class="v34-budget-overline">${esc(b.name)} ／ 2026年度 当初予算</span><strong>${f(b.value,2)}億円</strong><small>一般会計の${f(b.value/512.3*100,1)}％</small></div>`;
 const parts=(b.officialParts||[]).map(([name,value,desc])=>({name,value:value/100000,desc}));
 const idx=d32.histLabels.indexOf(b.name);
 const hist=idx>=0?Object.entries(d32.history).sort(([a],[b])=>+a-+b).map(([year,row])=>({year:+year,value:row[idx]})):[];
 const showTable=!!bmode[b.key];
 let content=`<div class="v33-budget-headline"><div class="v33-eyebrow">INSIDE & HISTORY</div><h4>何に使う？ その額はどう変わった？</h4><p>左は2026年度予算の内訳、右は2016〜2025年度の決算推移。<b>予算と決算は別の数字</b>です。</p></div><div class="v33-budget-split"><div class="v33-budget-plot"><div class="v33-budget-sub"><strong>内訳</strong><span>2026年度当初予算／億円</span></div>${parts.length?budgetBars(parts,b.value):'<p>細分した予算項目が確認できません。</p>'}</div><div class="v33-budget-plot"><div class="v33-budget-sub"><strong>10年間の推移</strong><span>2016–2025年度決算／億円</span></div>${hist.length?plot({years:hist.map(x=>x.year),title:b.name+'の10年決算額',unit:'億円',width:570,height:258,axisMin:0,series:[{name:b.name,values:hist.map(x=>x.value),color:'#178361'}],readoutId:'v33BudgetReadout'}):'<p>この予算費目に対応する決算系列はありません。</p>'}</div></div>`;
 content+=`<div id="v33BudgetReadout" class="v33-data-readout" aria-live="polite">内訳の棒または推移の点を押すと、ここに数値を表示します。</div><div class="v33-budget-footer"><button type="button" class="v33-outline-btn" id="v33BudgetToggle">${showTable?'グラフを中心に見る':'数値表も見る'}</button><span>同じ画面内で内訳と推移を比較できます</span></div>`;
 if(showTable){content+=`<div class="v33-budget-tables">${table(['区分','2026年度当初予算（億円）','費目内の割合','用途'],parts.map(x=>[x.name,f(x.value,2),f(x.value/b.value*100,1)+'％',x.desc]))}${hist.length?table(['年度',b.name+'（決算・億円）'],hist.map(x=>[x.year,f(x.value,2)])):''}</div>`;}
 $('v32BudgetChart').innerHTML=content;
 $('v32BudgetNote').textContent='内訳＝2026年度一般会計当初予算「項」。推移＝2016〜2025年度普通会計決算の「款」。会計年度と予算・決算の定義が異なるため、線を2026年まで接続していません。';
 const t=$('v33BudgetToggle');t?.addEventListener('click',()=>{bmode[b.key]=!bmode[b.key];renderBudget();});
}
function budgetControls(){
 $('v32BudgetSelect')?.addEventListener('click',e=>{const x=e.target.closest('[data-v33-expense]');if(x){currentExpense=x.dataset.v33Expense;renderBudget();}});
 const title=$('budgetSelectedTitle');
 if(title){new MutationObserver(()=>{const obj=budget.find(x=>x.name===title.textContent.trim());if(obj&&currentExpense!==obj.key){currentExpense=obj.key;renderBudget()}}).observe(title,{childList:true,subtree:true,characterData:true});}
}
const popRows=[
 [2020,748,1357,4475,4796],
 [2021,733,1431,4769,4303],
 [2022,646,1619,4752,4976],
 [2023,672,1545,4883,4930],
 [2024,597,1674,5000,5012]
];
function population(){
 const width=890,height=318,L=60,R=66,top=34,base=252,years=popRows.map(r=>r[0]);
 const xx=i=>L+i*(width-L-R)/(years.length-1);
 const yl=v=>base-v/1900*(base-top),yr=v=>base-(v-3800)/(5400-3800)*(base-top);
 let svg=`<div class="v33-svg-wrap"><svg viewBox="0 0 ${width} ${height}" role="group" aria-label="出生、死亡、転入、転出の5年間を1画面で比較">`;
 for(let j=0;j<5;j++){
  let y=top+j*(base-top)/4;
  svg+=`<line x1="${L}" x2="${width-R}" y1="${y}" y2="${y}" stroke="#dce8df" stroke-dasharray="3 5"/><text x="${L-8}" y="${y+4}" text-anchor="end" font-size="11">${Math.round(1900*(1-j/4))}</text><text x="${width-R+8}" y="${y+4}" font-size="11">${Math.round(5400-1600*(j/4))}</text>`;
 }
 const lines=[{name:'出生',column:1,c:'#19906a',fn:yl},{name:'死亡',column:2,c:'#b78040',fn:yl},{name:'転入',column:3,c:'#5877b3',fn:yr},{name:'転出',column:4,c:'#bc6b83',fn:yr}];
 for(let row of lines){
   const path=popRows.map((r,i)=>(i?'L':'M')+xx(i)+','+row.fn(r[row.column])).join(' ');
   svg+=`<path d="${path}" fill="none" stroke="${row.c}" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>`;
   popRows.forEach((r,i)=>{svg+=`<circle role="button" tabindex="0" data-plot="v33PopReadout" data-year="${r[0]}" data-name="${row.name}" data-value="${r[row.column].toLocaleString('ja-JP')}" data-unit="人" cx="${xx(i)}" cy="${row.fn(r[row.column])}" r="6.5" fill="${row.c}" stroke="white" stroke-width="2.5"/>`;});
 }
 years.forEach((y,i)=>{svg+=`<text x="${xx(i)}" y="${base+24}" text-anchor="middle" font-size="12">${y}</text>`});
 svg+=`<text x="${L}" y="17" font-size="12">左軸：出生・死亡（人）</text><text x="${width-R}" y="17" font-size="12" text-anchor="end">右軸：転入・転出（人）</text></svg></div><div class="v33-line-legend">${lines.map(r=>`<span><i style="background:${r.c}"></i>${r.name}</span>`).join('')}</div>`;
 $('v33PopChart').innerHTML=svg;
 $('v33PopTable').innerHTML=table(['年','出生（人）','死亡（人）','国内転入（人）','国内転出（人）'],popRows);
}
